+func reapShimSubtree() ([]string, error) {
+	self := os.Getpid()
+	var ended []string
+	seen := map[int]bool{}
+	deadline := time.Now().Add(reviewReapWait)
+	// A process that cannot be inspected or ended is not a reason to stop:
+	// the others are still ended, and the problem is reported at the end
+	// (review round 9, N3).
+	var problems []string
+	note := func(err error) {
+		if len(problems) < 8 {
+			problems = append(problems, err.Error())
+		}
+	}
+	for {
+		children := 0
+		problems = problems[:0]
+		dirs, err := os.ReadDir("/proc")
+		if err != nil {
+			note(fmt.Errorf("the run's processes could not be listed: %w", err))
+		}
+		for _, d := range dirs {
+			pid, err := strconv.Atoi(d.Name())
+			if err != nil || pid == self {
+				continue
+			}
+			st, err := readShimProcStat(pid)
+			if reviewProcessGoneErr(err) {
+				continue
+			}
+			if err != nil {
+				// A process of another user is never the run's: with procfs
+				// mounted hidepid it is visible and unreadable (review round 10,
+				// N1). Only one of this user is an unknown that may be the run's.
+				if owner, oerr := reviewProcessOwner(pid); reviewProcessGoneErr(oerr) || oerr == nil && owner != os.Getuid() {
+					continue
+				}
+				children++
+				note(fmt.Errorf("process %d could not be inspected: %w", pid, err))
+				continue
+			}
+			if st.ppid != self {
+				continue
+			}
+			children++
+			if !st.zombie {
+				// A pid is reported ended only once its signal was delivered
+				// (review round 10, N3).
+				if err := killPinnedChild(pid, self); err != nil {
+					note(err)
+				} else if !seen[pid] {
+					seen[pid] = true
+					ended = append(ended, strconv.Itoa(pid))
+				}
+			}
+		}
+		for {
+			pid, err := unix.Wait4(-1, nil, unix.WNOHANG, nil)
+			if pid <= 0 || err != nil {
+				break
+			}
+		}
+		if children == 0 && len(problems) == 0 {
+			return ended, nil
+		}
+		if time.Now().After(deadline) {
+			return ended, fmt.Errorf("%d process(es) of the run could not be ended: %s", children, strings.Join(problems, "; "))
+		}
+		time.Sleep(20 * time.Millisecond)
+	}
+}
